package com.swiftpay.ledger.entity;
import com.fasterxml.jackson.databind.annotation.JsonSerialize; import com.fasterxml.jackson.databind.ser.std.ToStringSerializer; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="transactions",uniqueConstraints=@UniqueConstraint(name="uk_ledger_transaction_id",columnNames="transaction_id"),indexes=@Index(name="idx_ledger_payer_created",columnList="payer_id,created_at")) public class LedgerTransaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="transaction_id",nullable=false) String transactionId; @Column(name="payer_id",nullable=false) String senderId; @Column(name="payee_id",nullable=false) String receiverId; @Column(nullable=false,precision=19,scale=4) @JsonSerialize(using=ToStringSerializer.class) BigDecimal amount; @Column(nullable=false) String currency; @Column(nullable=false) String status; @Column(nullable=false) Instant createdAt; protected LedgerTransaction(){} public LedgerTransaction(String id,String sender,String receiver,BigDecimal amount,String currency,String status,Instant createdAt){transactionId=id;senderId=sender;receiverId=receiver;this.amount=amount;this.currency=currency;this.status=status;this.createdAt=createdAt;} public String getTransactionId(){return transactionId;} public String getSenderId(){return senderId;} public String getReceiverId(){return receiverId;} public BigDecimal getAmount(){return amount;} public String getCurrency(){return currency;} public String getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public void complete(){status="COMPLETED";} public void fail(){status="FAILED";} }